/* Demo mode: answers every API call in the browser from sample data. Only bundled when REACT_APP_DEMO=1. */
import DATA from "./demo-data.json";

const F = JSON.parse(JSON.stringify(DATA));
const IMG = F.__slip_images || {};
export const DEMO_TODAY = F.__today;
const uid = () => Math.random().toString(36).slice(2, 12);
const nowIso = () => new Date().toISOString();

// keep "online" devices looking live
F["/devices"].devices.forEach((d) => { if (d.status === "online") d.last_seen = nowIso(); });
F["/dashboard"].devices.forEach((d) => { if (d.status === "online") d.last_seen = nowIso(); });

// the sandboxed viewer has no confirm/prompt dialogs
window.confirm = () => true;
window.prompt = (_m, def) => (def != null ? def : "demo123");

function overlay(html) {
  const bg = document.createElement("div");
  bg.className = "modal-bg";
  bg.innerHTML = `<div class="modal wide">${html}</div>`;
  bg.addEventListener("mousedown", (e) => { if (e.target === bg || e.target.closest("[data-close]")) bg.remove(); });
  document.body.appendChild(bg);
}

export function demoPdf(path) {
  const id = path.split("/")[2];
  const img = IMG[id];
  overlay(`<div class="modal-h"><h2>Salary slip (PDF preview)</h2><button class="x" data-close>×</button></div>
    <div class="modal-b" style="background:#e9ecf2;text-align:center">${img ? `<img src="${img}" alt="Salary slip" style="max-width:100%;box-shadow:0 6px 24px rgba(0,0,0,.18);border-radius:4px"/>`
      : `<p class="muted">Slips are generated as A4 PDFs in the installed app.</p>`}</div>
    <div class="modal-f"><span class="small muted" style="margin-right:auto">In the real app this opens the A4 PDF and is also sent on WhatsApp.</span><button class="btn" data-close>Close</button></div>`);
}

export function demoDownload(path, filename) {
  const kind = filename.endsWith(".pdf") ? "a print-ready PDF with your shop logo" : filename.endsWith(".xlsx") ? "an Excel sheet (colour-coded, with totals and your shop name)" : "a CSV file";
  overlay(`<div class="modal-h"><h2>${filename}</h2><button class="x" data-close>×</button></div>
    <div class="modal-b"><p>In the installed app this downloads <b>${filename}</b> — ${kind}.</p>
    <p class="muted small">Downloads are switched off in this online demo.</p></div><div class="modal-f"><button class="btn" data-close>OK</button></div>`);
}

const emptyTotals = { gross: 0, deductions: 0, net: 0, count: 0, final: 0 };
function totals(rows) {
  return { gross: rows.reduce((a, r) => a + r.gross, 0), deductions: rows.reduce((a, r) => a + r.total_deductions, 0),
    net: rows.reduce((a, r) => a + r.net, 0), count: rows.length, final: rows.filter((r) => r.status === "final").length };
}
const emps = () => F["/employees?active=1"];
let hidden = [];
const roster = {};      // "eid|date" -> shift id | "OFF"
const addDays = (ds, n) => { const d = new Date(ds + "T00:00:00Z"); d.setUTCDate(d.getUTCDate() + n); return d.toISOString().slice(0, 10); };
const shiftOn = (e, ds) => {
  const r = roster[`${e.id}|${ds}`];
  if (r && r !== "OFF") return [r, r];
  let sid = e.shift_id;
  (e.shift_history || []).slice().sort((a, b) => a.from.localeCompare(b.from)).forEach((h) => { if (h.from <= ds) sid = h.shift_id; });
  return [sid, r];
};
function buildRoster(from, to) {
  const shifts = F["/shifts"]; const def = shifts.find((x) => x.is_default) || shifts[0];
  const days = []; for (let d = from; d <= to; d = addDays(d, 1)) days.push(d);
  const rows = emps().map((e) => ({
    employee: { id: e.id, code: e.code, name: e.name, department: e.department, photo_url: e.photo_url },
    cells: days.map((ds) => {
      const [sid, rv] = shiftOn(e, ds);
      const sh = shifts.find((x) => x.id === sid) || def;
      const wd = (new Date(ds + "T00:00:00Z").getUTCDay() + 6) % 7;
      const wo = e.weekly_off != null ? e.weekly_off : sh.weekly_off || [6];
      return { shift_id: sh.id, off: rv === "OFF" || (!rv && wo.includes(wd)), set: rv || null };
    }),
  }));
  return { days, rows, shifts };
}
function changeShift(e, sid, from, note) {
  let h = (e.shift_history || []).slice();
  if (!h.length) h = [{ from: "1900-01-01", shift_id: e.shift_id, note: "original" }];
  h = h.filter((x) => x.from !== from); h.push({ from, shift_id: sid, note }); h.sort((a, b) => a.from.localeCompare(b.from));
  e.shift_history = h;
  e.shift_id = h.filter((x) => x.from <= DEMO_TODAY).pop()?.shift_id ?? e.shift_id;
}

// ---- advances (same rules as the server) ----
const ADV = () => F["/advances"];
const monthEnd = (m) => m + "-31";
function recalcAdv(r) {
  if (r.status === "final") return r;
  const base = r.deductions.filter((d) => d.name !== "Advance recovery");
  const room = Math.max(0, r.gross - base.reduce((a, d) => a + d.amount, 0));
  const chosen = (r.adjustments || {}).advance || {};
  let tot = 0; const lines = [];
  ADV().filter((a) => a.employee_id === r.employee_id && a.balance > 0 && a.date <= monthEnd(r.month)).forEach((a) => {
    const ch = chosen[a.id];
    const want = ch !== undefined && ch !== "" ? +ch : a.auto !== false && a.installment > 0 ? a.installment : 0;
    const take = Math.max(0, Math.min(a.balance, want, room - tot));
    if (take > 0) { tot += take; lines.push({ advance_id: a.id, amount: take }); }
  });
  r.deductions = tot ? [...base, { name: "Advance recovery", amount: tot }] : base;
  r.advance_recoveries = lines;
  r.total_deductions = r.deductions.reduce((a, d) => a + d.amount, 0);
  r.net = Math.max(0, Math.round(r.gross - r.total_deductions));
  r.advance_balance = ADV().filter((a) => a.employee_id === r.employee_id && a.balance > 0).reduce((x, a) => x + a.balance, 0) - tot;
  return r;
}
function advRows(month) {
  const p = F[`/payroll?month=${month}`];
  return ADV().filter((a) => a.date <= monthEnd(month)).map((a) => {
    const sl = p?.rows.find((r) => r.employee_id === a.employee_id);
    const taken = (sl?.advance_recoveries || []).find((x) => x.advance_id === a.id)?.amount || 0;
    if (a.balance <= 0 && !(sl?.status === "final" && taken)) return null;
    const ch = ((sl?.adjustments || {}).advance || {})[a.id];
    return { advance_id: a.id, employee_id: a.employee_id, employee_name: a.employee_name, emp_code: a.emp_code, date: a.date, amount: a.amount,
      balance: a.balance, installment: a.installment || 0, auto: a.auto !== false, note: a.note || "", this_month: taken,
      chosen: ch === undefined ? null : ch, slip_id: sl?.id || null, slip_status: sl?.status || null, net: sl?.net ?? null };
  }).filter(Boolean);
}
const refreshTotals = (m) => { const p = F[`/payroll?month=${m}`]; if (p) p.totals = totals(p.rows); };

function handle(method, url, body) {
  const [path, qs] = url.split("?");
  const q = Object.fromEntries(new URLSearchParams(qs || ""));
  const seg = path.split("/").filter(Boolean);
  const ok = { ok: true };

  if (method === "get") {
    if (path === "/ignored-codes") return hidden;
    if (path === "/roster") return buildRoster(q.from_date, q.to_date);
    if (seg[0] === "shifts" && seg[1] === "history") {
      const e = emps().find((x) => x.id === seg[2]);
      return (e?.shift_history || []).slice().sort((a, b) => b.from.localeCompare(a.from));
    }
    if (path === "/punches") {
      let rows = F[`/punches?date=${q.date}`] || [];
      if (q.emp_code) rows = rows.filter((p) => p.emp_code === q.emp_code);
      return rows;
    }
    if (path === "/advances") return ADV().map((a) => ({ ...a, auto: a.auto !== false, recovered: a.amount - a.balance }));
    if (path === "/payroll/advances") return advRows(q.month);
    if (F[url] !== undefined) return F[url];
    if (path === "/attendance/daily") return { rows: [], labels: {} };
    if (path === "/attendance/monthly") return { days: [], rows: [] };
    if (path === "/payroll") return F[`/payroll?month=${q.month}`] || { rows: [], totals: emptyTotals };
    if (path === "/leaves") return F[url] || [];
    if (path === "/holidays") return F["/holidays?year=2026"].filter((h) => !q.year || h.date.startsWith(q.year));
    if (path === "/admin/companies" || path === "/admin/unknown-devices") return [];
    return [];
  }

  // ---- writes (kept in memory for this visit) ----
  if (path === "/auth/register-shop") throw err("Sign-up is switched off in this demo. In the real app the shop is created and opens straight away.");
  if (path === "/roster" && method === "put") { (body.cells || []).forEach((c) => { const k = `${c.employee_id}|${c.date}`; if (c.shift_id) roster[k] = c.shift_id; else delete roster[k]; }); return { ok: true, saved: (body.cells || []).length }; }
  if (path === "/roster/pattern") {
    let n = 0;
    for (let d = body.from_date; d <= body.to_date; d = addDays(d, 1)) {
      const wd = (new Date(d + "T00:00:00Z").getUTCDay() + 6) % 7;
      const idx = Math.round((new Date(d) - new Date(body.from_date)) / 86400000);
      let v = body.mode === "rotate" ? ((body.off_days || []).includes(wd) ? "OFF" : body.rotation[Math.floor(idx / Math.max(1, +body.every || 7)) % body.rotation.length]) : body.week[wd];
      body.employee_ids.forEach((eid) => { const k = `${eid}|${d}`; if (v === "CLEAR") delete roster[k]; else if (v) { roster[k] = v; n++; } });
    }
    return { ok: true, saved: n };
  }
  if (path === "/shifts/change") {
    emps().filter((e) => body.employee_ids.includes(e.id)).forEach((e) => changeShift(e, body.shift_id, body.from_date, body.note));
    return { ok: true, changed: body.employee_ids.length };
  }
  if (seg[0] === "shifts" && seg[1] === "history" && seg[3] === "remove") {
    const e = emps().find((x) => x.id === seg[2]);
    if (e) { e.shift_history = (e.shift_history || []).filter((h) => h.from !== body.from); e.shift_id = e.shift_history.filter((x) => x.from <= DEMO_TODAY).pop()?.shift_id ?? e.shift_id; }
    return ok;
  }
  if (path === "/employees/bulk") {
    let saved = 0; const errors = [];
    (body.rows || []).forEach((r) => {
      const e = emps().find((x) => x.id === r.id); if (!e) return;
      if ("name" in r && !String(r.name).trim()) { errors.push(`${e.code}: name cannot be empty`); return; }
      ["name", "phone", "department", "designation", "salary_type", "joining_date", "daily_rate", "hourly_rate"].forEach((k) => { if (k in r) e[k] = r[k]; });
      if ("monthly" in r) {
        const lines = (e.earnings || []).filter((x) => +x.amount); const old = lines.reduce((a, b) => a + +b.amount, 0);
        e.earnings = lines.length > 1 && old ? lines.map((x) => ({ name: x.name, amount: Math.round(+x.amount * r.monthly / old) })) : [{ name: lines[0]?.name || "Basic", amount: +r.monthly }];
      }
      if ("shift_id" in r && r.shift_id !== e.shift_id) changeShift(e, r.shift_id, DEMO_TODAY, "quick edit");
      saved++;
    });
    return { ok: true, saved, errors };
  }
  if (seg[0] === "employees" && seg[2] === "photo") {
    const e = emps().find((x) => x.id === seg[1]);
    if (method === "delete") { if (e) e.photo_url = null; return ok; }
    if (e) e.photo_url = body.data;
    return { ok: true, photo_url: body.data };
  }
  if (path === "/devices/push-names") {
    const n = body.employee_ids ? body.employee_ids.length : emps().length;
    const devs = F["/devices"].devices.filter((d) => !body.device_ids || body.device_ids.includes(d.id));
    const msg = { agent: "Sent to the LAN agent — names are written within a minute", adms: `${n} names queued — the machine applies them on its next check-in`,
      hik_push: "Hikvision push mode can't write to the terminal. Use LAN agent or static IP mode.", direct: `${n} renamed` };
    return { employees: n, results: devs.map((d) => ({ device: d.name, mode: d.mode, ok: d.mode !== "hik_push", message: msg[d.mode] })) };
  }
  if (path === "/sync/all") {
    let added = 0;
    if (body.auto_add) {
      F["/device-users"].forEach((u) => emps().push({ id: uid(), code: u.user_code, name: u.name || `Employee ${u.user_code}`, salary_type: "monthly", earnings: [{ name: "Basic", amount: 0 }], active: true }));
      added = F["/device-users"].length; F["/device-users"] = [];
    }
    F["/company"].settings.auto_add_employees = !!body.auto_add;
    const msg = { agent: "Sent to the LAN agent — it fetches within a minute", adms: "Queued — the machine uploads on its next check-in (about 30 s)",
      hik_push: "Live push — punches already arrive in real time", direct: "3 new punches, 14 users on machine" };
    return { ok: true, employees_added: added, results: F["/devices"].devices.map((d) => ({ device: d.name, mode: d.mode, ok: true, message: msg[d.mode] })) };
  }
  if (path === "/employees/bulk-delete") {
    const ids = body.ids || [];
    const moving = emps().filter((e) => ids.includes(e.id));
    F["/employees?active=1"] = emps().filter((e) => !ids.includes(e.id));
    if (body.permanent) {
      F["/employees?active=0"] = F["/employees?active=0"].filter((e) => !ids.includes(e.id));
      if (body.ignore) hidden = [...new Set([...hidden, ...moving.map((e) => e.code)])];
      return { ok: true, deleted: ids.length };
    }
    moving.forEach((e) => F["/employees?active=0"].push({ ...e, active: false, leaving_date: DEMO_TODAY }));
    return { ok: true, marked_left: moving.length };
  }
  if (path === "/device-users/remove") {
    hidden = [...new Set([...hidden, ...body.codes])];
    F["/device-users"] = F["/device-users"].filter((u) => !body.codes.includes(u.user_code)); return ok;
  }
  if (path === "/ignored-codes/restore") {
    hidden = hidden.filter((c) => !body.codes.includes(c));
    return { ok: true, message: "Restored. Run Sync all with history to bring their punches back." };
  }
  if (seg[0] === "punches" && method === "delete") { delPunches((p) => p.id === seg[1]); return ok; }
  if (path === "/punches/delete") { return { ok: true, deleted: delPunches((p) => body.ids.includes(p.id)) }; }
  if (path === "/punches/delete-range") {
    const match = (p, day) => day >= body.from_date && day <= (body.to_date || body.from_date) && (!body.emp_code || p.emp_code === body.emp_code)
      && (!body.device_id || p.device_id === body.device_id);
    if (body.dry_run) {
      let n = 0;
      Object.keys(F).filter((k) => k.startsWith("/punches?date=")).forEach((k) => { const day = k.slice(14); n += F[k].filter((p) => match(p, day)).length; });
      return { count: n };
    }
    return { ok: true, deleted: delPunches(match) };
  }
  if (path === "/payroll/month" && method === "delete") {
    const k = `/payroll?month=${q.month}`; const n = F[k] ? F[k].rows.length : 0;
    if (F[k] && F[k].rows.some((r) => r.status === "final")) throw err("This month is finalised. Unlock it first, then delete.");
    delete F[k]; return { ok: true, deleted: n };
  }
  if (seg[0] === "payroll" && seg.length === 2 && method === "delete") {
    Object.keys(F).filter((k) => k.startsWith("/payroll?")).forEach((k) => { F[k].rows = F[k].rows.filter((r) => r.id !== seg[1]); F[k].totals = totals(F[k].rows); });
    return ok;
  }
  if (path === "/whatsapp/logs" && method === "delete") { const n = F["/whatsapp/logs"].length; F["/whatsapp/logs"] = []; return { ok: true, deleted: n }; }
  if (path === "/auth/login") return { token: "demo", user: F["/auth/me"].user };
  if (path === "/auth/logout-all" || path === "/auth/change-password") return { ok: true, token: "demo" };
  if (path === "/employees" && method === "post") {
    if (!body.code || !body.name) throw err("Device user ID and name are required");
    if (emps().some((e) => e.code === String(body.code))) throw err(`Device ID ${body.code} is already given to another employee`);
    const e = { ...body, id: uid(), code: String(body.code), active: true, extra_codes: String(body.extra_codes || "").split(",").map((x) => x.trim()).filter(Boolean) };
    emps().push(e); return e;
  }
  if (seg[0] === "employees" && seg[1] && seg[1] !== "bulk" && method === "put") {
    const all = [...emps(), ...F["/employees?active=0"]];
    const e = all.find((x) => x.id === seg[1]);
    Object.assign(e, body, typeof body.extra_codes === "string" ? { extra_codes: body.extra_codes.split(",").map((x) => x.trim()).filter(Boolean) } : {});
    if (body.active === true) { F["/employees?active=0"] = F["/employees?active=0"].filter((x) => x.id !== e.id); emps().push(e); }
    return e;
  }
  if (seg[0] === "employees" && method === "delete") {
    const e = emps().find((x) => x.id === seg[1]);
    F["/employees?active=1"] = emps().filter((x) => x.id !== seg[1]);
    if (e) F["/employees?active=0"].push({ ...e, active: false, leaving_date: DEMO_TODAY });
    return ok;
  }
  if (path === "/device-users/import") {
    const picked = F["/device-users"].filter((u) => body.codes.includes(u.user_code));
    picked.forEach((u) => emps().push({ id: uid(), code: u.user_code, name: u.name || `Employee ${u.user_code}`, salary_type: "monthly", earnings: [{ name: "Basic", amount: 0 }], active: true, ot_allowed: true }));
    F["/device-users"] = F["/device-users"].filter((u) => !body.codes.includes(u.user_code));
    return { added: picked.length };
  }
  if (path === "/employees/import-csv") return { added: 0, updated: 0, errors: ["CSV import is available in the installed app"] };

  if (path === "/devices" && method === "post") {
    const d = { ...body, id: uid(), status: "new", push_token: uid() + uid(), total_punches: 0, port: body.port || (body.brand === "hikvision" ? 80 : 4370) };
    F["/devices"].devices.push(d); return d;
  }
  if (seg[0] === "devices" && seg[1]) {
    const d = F["/devices"].devices.find((x) => x.id === seg[1]);
    if (method === "put") { Object.assign(d, body); return ok; }
    if (method === "delete") { F["/devices"].devices = F["/devices"].devices.filter((x) => x.id !== seg[1]); return ok; }
    if (seg[2] === "test") return { ok: true, message: "Connected", device_time: `${DEMO_TODAY} 11:30:12`, users: 14, records: 4810 };
    if (seg[2] === "sync") return { ok: true, message: d.mode === "adms" ? "Re-upload command queued — the machine will send its logs on its next check-in." : "Sync requested — the LAN agent will fetch on its next round (within a minute)." };
    if (seg[2] === "fetch-users") return { ok: true, message: "User list request sent to the machine." };
  }

  if (path === "/attendance/manual") {
    const day = F[`/attendance/daily?date=${body.date}`];
    const r = day && day.rows.find((x) => x.employee_id === body.employee_id);
    if (r) { r.manual_status = body.status; r.status = body.status || r.auto_status; r.manual_remark = body.remark; }
    return r || ok;
  }
  if (path === "/attendance/manual-punch") {
    const day = F[`/attendance/daily?date=${body.date}`];
    const r = day && day.rows.find((x) => x.employee_id === body.employee_id);
    if (r) {
      r.punches = [...(r.punches || []), body.time].sort();
      r.in_time = r.punches[0]; r.out_time = r.punches.length > 1 ? r.punches[r.punches.length - 1] : null;
      if (r.out_time) { const m = (t) => +t.slice(0, 2) * 60 + +t.slice(3, 5); r.work_minutes = m(r.out_time) - m(r.in_time); r.status = r.auto_status = r.work_minutes >= 420 ? "P" : r.work_minutes >= 240 ? "HD" : "A"; }
      const e = emps().find((x) => x.id === body.employee_id);
      (F[`/punches?date=${body.date}`] = F[`/punches?date=${body.date}`] || []).unshift({ id: uid(), ts: `${body.date} ${body.time}:00`, emp_code: e?.code, employee_name: e?.name, device_name: "Manual", source: "manual", added_by: "Owner" });
    }
    return ok;
  }
  if (path === "/attendance/reprocess") return { ok: true, days_processed: 12 };

  if (path === "/payroll/generate") {
    const p = F[`/payroll?month=${body.month}`];
    if (!p) return { ok: true, generated: 0, locked_skipped: 0, _note: "demo" };
    p.rows.forEach(recalcAdv); refreshTotals(body.month);
    return { ok: true, generated: p.rows.filter((r) => r.status !== "final").length, locked_skipped: p.rows.filter((r) => r.status === "final").length };
  }
  if (path === "/payroll/finalize" || path === "/payroll/unlock") {
    const p = F[`/payroll?month=${body.month}`];
    if (p) {
      const fin = path.endsWith("finalize");
      p.rows.forEach((r) => {
        if (fin === (r.status === "final")) return;
        (r.advance_recoveries || []).forEach((rec) => {
          const a = ADV().find((x) => x.id === rec.advance_id); if (!a) return;
          if (fin) { a.balance = Math.max(0, a.balance - rec.amount); a.recoveries = [...(a.recoveries || []), { month: body.month, amount: rec.amount, payslip_id: r.id }]; }
          else { a.balance += rec.amount; a.recoveries = (a.recoveries || []).filter((x) => x.payslip_id !== r.id); }
        });
        r.status = fin ? "final" : "draft";
      });
      p.totals = totals(p.rows);
    }
    return { ok: true, finalized: p ? p.rows.length : 0, unlocked: p ? p.rows.length : 0 };
  }
  if (seg[0] === "payroll" && seg[2] === "adjust") {
    for (const k of Object.keys(F)) {
      if (!k.startsWith("/payroll?")) continue;
      const r = F[k].rows.find((x) => x.id === seg[1]);
      if (!r) continue;
      const strip = (arr) => arr.filter((x) => !x.manual);
      const add = (body.additions ?? r.adjustments?.additions ?? []).filter((a) => +a.amount).map((a) => ({ name: a.name || "Addition", amount: +a.amount, manual: true }));
      const ded = (body.deductions ?? r.adjustments?.deductions ?? []).filter((a) => +a.amount).map((a) => ({ name: a.name || "Deduction", amount: +a.amount, manual: true }));
      r.earnings = [...strip(r.earnings), ...add]; r.deductions = [...strip(r.deductions), ...ded];
      r.gross = r.earnings.reduce((a, x) => a + x.amount, 0); r.total_deductions = r.deductions.reduce((a, x) => a + x.amount, 0);
      const prev = r.adjustments || {};
      r.adjustments = { additions: body.additions ?? prev.additions ?? [], deductions: body.deductions ?? prev.deductions ?? [], advance: body.advance ?? prev.advance ?? {} };
      r.net = Math.max(0, Math.round(r.gross - r.total_deductions));
      recalcAdv(r); F[k].totals = totals(F[k].rows); return r;
    }
  }
  if (path === "/payroll/send-whatsapp") {
    const p = F[`/payroll?month=${body.month}`] || { rows: [] };
    const rows = body.slip_ids ? p.rows.filter((r) => body.slip_ids.includes(r.id)) : p.rows;
    rows.forEach((r) => (r.whatsapp_status = "sent"));
    return { sent: rows.length, results: rows.map((r) => ({ employee: r.employee_name, status: "sent", response: "Demo: message accepted by panel" })) };
  }

  if (path === "/leaves" && method === "post") {
    const e = emps().find((x) => x.id === body.employee_id);
    if (!e) throw err("Employee not found");
    const key = `/leaves?month=${body.from_date.slice(0, 7)}`;
    (F[key] = F[key] || []).unshift({ id: uid(), date: body.from_date, employee_name: e.name, type: body.type, paid: body.paid, reason: body.reason });
    return ok;
  }
  if (seg[0] === "leaves" && method === "delete") { Object.keys(F).filter((k) => k.startsWith("/leaves?")).forEach((k) => (F[k] = F[k].filter((x) => x.id !== seg[1]))); return ok; }
  if (path === "/holidays" && method === "post") { F["/holidays?year=2026"].push({ id: uid(), date: body.date, name: body.name || "Holiday" }); F["/holidays?year=2026"].sort((a, b) => a.date.localeCompare(b.date)); return ok; }
  if (seg[0] === "holidays" && method === "delete") { F["/holidays?year=2026"] = F["/holidays?year=2026"].filter((x) => x.id !== seg[1]); return ok; }
  if (path === "/advances" && method === "post") {
    const e = emps().find((x) => x.id === body.employee_id);
    if (!e || !(+body.amount > 0)) throw err("Choose an employee and amount");
    const inst = +body.installment || 0;
    F["/advances"].unshift({ id: uid(), employee_id: e.id, employee_name: e.name, emp_code: e.code, date: body.date || DEMO_TODAY, amount: +body.amount, balance: +body.amount,
      installment: inst, auto: inst > 0, note: body.note || "", recoveries: [] });
    Object.keys(F).filter((k) => k.startsWith("/payroll?")).forEach((k) => { F[k].rows.forEach(recalcAdv); F[k].totals = totals(F[k].rows); });
    return ok;
  }
  if (path === "/payroll/advance-deductions") {
    const p = F[`/payroll?month=${body.month}`]; let n = 0;
    if (p) p.rows.forEach((r) => {
      if (r.status === "final") return;
      const mine = ADV().filter((a) => a.employee_id === r.employee_id && a.id in body.amounts);
      if (!mine.length) return;
      const cur = { ...((r.adjustments || {}).advance || {}) };
      mine.forEach((a) => { const v = body.amounts[a.id]; if (v === "" || v == null) delete cur[a.id]; else cur[a.id] = Math.max(0, +v); });
      r.adjustments = { ...(r.adjustments || {}), advance: cur }; recalcAdv(r); n++;
    });
    refreshTotals(body.month);
    return { ok: true, updated: n, no_slip: 0, locked: 0 };
  }
  if (seg[0] === "advances" && seg[2] === "repay") {
    const a = ADV().find((x) => x.id === seg[1]); const amt = Math.min(+body.amount || 0, a.balance);
    a.balance -= amt; a.recoveries = [...(a.recoveries || []), { month: "", amount: amt, cash: true, date: DEMO_TODAY }]; return a;
  }
  if (seg[0] === "advances" && method === "put") {
    const a = ADV().find((x) => x.id === seg[1]);
    if ("installment" in body) { a.installment = +body.installment || 0; a.auto = a.installment > 0; }
    if ("note" in body) a.note = body.note; if (body.date) a.date = body.date;
    if (body.amount) { const rec = a.amount - a.balance; a.amount = +body.amount; a.balance = Math.max(0, a.amount - rec); }
    Object.keys(F).filter((k) => k.startsWith("/payroll?")).forEach((k) => { F[k].rows.forEach(recalcAdv); F[k].totals = totals(F[k].rows); });
    return a;
  }
  if (seg[0] === "advances" && method === "delete") { F["/advances"] = F["/advances"].filter((x) => x.id !== seg[1]); return ok; }
  if (path === "/shifts" && method === "post") { F["/shifts"].push({ ...body, id: uid() }); return ok; }
  if (seg[0] === "shifts" && method === "put") { if (body.is_default) F["/shifts"].forEach((s) => (s.is_default = false)); Object.assign(F["/shifts"].find((s) => s.id === seg[1]), body); return ok; }
  if (seg[0] === "shifts" && method === "delete") { F["/shifts"] = F["/shifts"].filter((s) => s.id !== seg[1]); return ok; }

  if (path === "/whatsapp/settings") { const w = F["/whatsapp/settings"]; Object.entries(body).forEach(([k, v]) => { if (k === "events") Object.entries(v).forEach(([ek, ev]) => Object.assign(w.events[ek], ev)); else if (!(k === "password" && !v)) w[k] = v; }); return w; }
  if (path === "/whatsapp/test") {
    const log = { id: uid(), event: "test", phone: body.phone, template: body.template, params: body.params, status: (body.phone || "").replace(/\D/g, "").length >= 10 ? "sent" : "failed", created_at: nowIso() };
    log.response = log.status === "sent" ? "Demo: message accepted by panel" : "Invalid mobile number";
    F["/whatsapp/logs"].unshift(log); return log;
  }
  if (path === "/whatsapp/run") return { count: body.event === "daily_summary" ? 1 : 0, results: [] };
  if (path === "/company/profile") { Object.assign(F["/company"], body); return ok; }
  if (path === "/company/settings") { Object.assign(F["/company"].settings, body); return F["/company"].settings; }
  if (path === "/company/users" && method === "post") { F["/company/users"].push({ id: uid(), name: body.name, email: body.email, role: body.role, active: true }); return ok; }
  if (seg[0] === "company" && seg[1] === "users") { Object.assign(F["/company/users"].find((u) => u.id === seg[2]) || {}, body.active !== undefined ? { active: body.active } : {}); return ok; }
  return ok;
}

function delPunches(test) {
  let n = 0;
  Object.keys(F).filter((k) => k.startsWith("/punches?date=")).forEach((k) => {
    const day = k.slice(14); const before = F[k].length;
    F[k] = F[k].filter((p) => !test(p, day)); n += before - F[k].length;
  });
  return n;
}

function err(detail) { const e = new Error(detail); e.demoDetail = detail; return e; }

export function demoAdapter(config) {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      let url = config.url;
      let body = config.data;
      try { if (typeof body === "string") body = JSON.parse(body); } catch { /* form data */ }
      try {
        const data = handle((config.method || "get").toLowerCase(), url, body || {});
        resolve({ data: JSON.parse(JSON.stringify(data)), status: 200, statusText: "OK", headers: {}, config, request: {} });
      } catch (e) {
        reject(Object.assign(new Error(e.message), { config, response: { status: 400, data: { detail: e.demoDetail || e.message } } }));
      }
    }, 120);
  });
}
